             sticky="we" if autowrap else "w", padx=8, pady=(0, 6))
    if autowrap:
        def _rewrap(event):
            try:
                w = max(240, event.width - 32)
                if abs(int(lbl.cget("wraplength")) - w) > 12:
                    lbl.configure(wraplength=w)
            except Exception:
                pass

        parent.bind("<Configure>", _rewrap, add="+")
    return lbl

